initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with id set to '${registration_id}' and registration update fragment set to '${registration_update_fragment}' and content-type set to 'application/ld+json'
}

